INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63397595', 63397595, 'analyze_legacy', 'Kab. Nganjuk', 'kabkota', 'Rumah Sakit Daerah Nganjuk', 'Belanja Jasa Penyelenggaraan Acara', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Nganjuk (Kab.)', 64650000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Belanja jasa penyelenggaraan acara merupakan pengadaan jasa pendukung pelaksanaan kegiatan kedinasan/kelembagaan yang bertujuan untuk mendukung kelancaran, ketertiban, dan keberhasilan kegiatan resmi instansi, meliputi penyediaan dekorasi acara, sarana transportasi kegiatan, serta jasa pelatih dan instruktur untuk mendukung kegiatan pembinaan, seremonial, dan peningkatan kebugaran. 1. Sewa Taman (Dekorasi Event) 2. Sewa Bus Study Banding 3. Biaya Pelatih Paduan Suara 4. Biaya Intruktur Senam Senam', '1. Sewa Taman (Dekorasi Event) Uraian Spesifik: Penyediaan jasa sewa taman/dekorasi event untuk mendukung pelaksanaan kegiatan resmi, seremonial, atau sosialisasi instansi. Spesifikasi: Jenis jasa: Jasa dekorasi dan penataan taman acara Ruang lingkup: Penyediaan tanaman hias, backdrop, ornamen pendukung, serta penataan area acara Standar kualitas: Rapi, estetis, dan sesuai tema acara resmi Waktu pelaksanaan: Sesuai jadwal kegiatan Pembongkaran: Dilakukan setelah kegiatan selesai Output: Area acara tertata dan layak digunakan 2. Sewa Bus Study Banding Uraian Spesifik: Penyediaan jasa transportasi berupa sewa bus untuk mendukung pelaksanaan kegiatan study banding/kegiatan kedinasan. Spesifikasi: Jenis jasa: Sewa bus pariwisata/kendaraan penumpang Kapasitas: Menyesuaikan jumlah peserta Kondisi kendaraan: Layak jalan, bersih, dan aman Fasilitas: AC dan kursi penumpang standar Pengemudi: Memiliki SIM yang sesuai dan berpengalaman Waktu sewa: Sesuai durasi kegiatan Output: Peserta tiba di lokasi tujuan dengan aman dan tepat waktu 3. Biaya Pelatih Paduan Suara Uraian Spesifik: Penyediaan jasa pelatih paduan suara dalam rangka pembinaan dan persiapan penampilan pada kegiatan resmi instansi. Spesifikasi: Jenis jasa: Jasa pelatih paduan suara Ruang lingkup: Latihan vokal, teknik bernyanyi, dan harmonisasi Frekuensi: Sesuai kebutuhan latihan Kompetensi: Memiliki pengalaman melatih paduan suara Waktu pelaksanaan: Sesuai jadwal yang disepakati Output: Peserta mampu menampilkan paduan suara sesuai standar acara 4. Biaya Instruktur Senam Uraian Spesifik: Penyediaan jasa instruktur senam untuk mendukung kegiatan kebugaran jasmani pegawai atau peserta kegiatan. Spesifikasi: Jenis jasa: Jasa instruktur senam Jenis senam: Senam kesehatan/senam kebugaran sesuai kebutuhan Durasi: Sesuai jadwal kegiatan Kompetensi: Memiliki pengalaman atau sertifikasi instruktur senam Metode: Aman, komunikatif, dan sesuai kemampuan peserta Output: Kegiatan senam terlaksana dengan tertib dan aman', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 920502);
