INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63377445', 63377445, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Penyediaan Jasa Tenaga Ahli Muda Pemanfaatan Teknologi Informasi Museum Kesejarahan Jakarta', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 226688000, 'June 2026', 'APBD', 1, 1, '4 Orang 4 Bulan', 'Pekerjaan ini meliputi penyediaan jasa Tenaga Ahli Muda untuk mendukung pelaksanaan kegiatan Pemanfaatan Teknologi Informasi Museum Kesejarahan Jakarta, yang mencakup perencanaan, pendampingan teknis, koordinasi, serta monitoring dan evaluasi pemanfaatan perangkat teknologi informasi dan multimedia museum. Tenaga Ahli Muda bertugas memberikan dukungan keahlian dalam integrasi sistem, pengelolaan konten digital, optimalisasi pemanfaatan perangkat TIK, penyusunan laporan teknis, serta memastikan kegiatan berjalan sesuai dengan rencana kerja, standar teknis, dan ketentuan yang berlaku.', 'Spesifikasi pekerjaan meliputi penyediaan Tenaga Ahli Muda sebanyak 4 (empat) orang dengan masa penugasan 4 (empat) bulan, berlatar belakang pendidikan minimal Strata 1 (S1) yang relevan dan memiliki pengalaman kerja minimal 4 (empat) tahun, yang bertanggung jawab dalam memberikan jasa konsultansi perorangan non konstruksi berupa pendampingan teknis pemanfaatan teknologi informasi museum, asistensi pengoperasian dan integrasi perangkat TIK, pengelolaan data dan konten digital, dukungan teknis kegiatan pameran berbasis teknologi, penyusunan laporan kemajuan dan laporan akhir, serta pelaksanaan tugas lainnya yang berkaitan langsung dengan kegiatan Pemanfaatan Teknologi Informasi Museum Kesejarahan Jakarta sesuai arahan Pejabat Pembuat Komitmen.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 922248);
