INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63354592', 63354592, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RUMAH SAKIT KANKER DHARMAIS JAKARTA', 'Pengadaan Jasa Pengendali Vektor dan Binatang Pembawa Penyakit Periode Januari Usulan Instalasi Kesehatan Lingkungan dan K3 PKN RS Kanker Dharmais DIPA BLU TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Barat (Kota)', 40935381, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Pengadaan Jasa Pengendali Vektor dan Binatang Pembawa Penyakit Periode Januari Usulan Instalasi Kesehatan Lingkungan dan K3 PKN RS Kanker Dharmais', '1. Ruang Lingkup Pekerjaan Penyedia jasa wajib melaksanakan kegiatan pengendalian vektor dan binatang pembawa penyakit untuk mencegah penyebaran penyakit menular dan menjaga kebersihan lingkungan kerja, yang meliputi: Pengendalian nyamuk, Pengendalian lalat, Pengendalian kecoa, Pengendalian tikus, Pengendalian serangga dan binatang pengganggu lainnya 2. Lokasi Pekerjaan Seluruh area lingkungan kerja, meliputi: Ruang kantor dan ruang pelayanan Gudang dan ruang arsip Area toilet dan saluran air Area luar bangunan (halaman, selokan, parkiran) Area khusus sesuai kebutuhan pengguna jasa 3. Jenis dan Metode Pekerjaan Pekerjaan dilaksanakan dengan metode sebagai berikut: a. Pengendalian Nyamuk Fogging/ULV (Ultra Low Volume), Larvasidasi pada tempat perindukan Pengasapan sesuai standar K3 b. Pengendalian Lalat, Penyemprotan residu, Pemasangan fly trap / lem lalat c. Pengendalian Kecoa, Penyemprotan insektisida residu, Pemasangan gel bait atau umpan kecoa d. Pengendalian Tikus, Pemasangan perangkap mekanik, Umpan rodentisida sesuai standar keselamatan 4. Frekuensi dan Jadwal Pelaksanaan, Periode pekerjaan: Januari 2026, Frekuensi: minimal 1 (satu) kali dalam periode kontrak atau sesuai kebutuhan pengguna jasa Jadwal pelaksanaan disepakati bersama dan tidak mengganggu aktivitas operasional 5. Bahan dan Peralatan Penyedia wajib menyediakan: Insektisida dan rodentisida berizin resmi Kementerian Kesehatan Alat fogging, sprayer, perangkap tikus, dan peralatan pendukung Alat Pelindung Diri (APD) lengkap untuk petugas 6. Persyaratan Penyedia Penyedia jasa wajib: Memiliki izin usaha pengendalian hama (Pest Control) Memiliki tenaga teknis yang berpengalaman dan bersertifikat Menggunakan bahan yang aman bagi manusia dan lingkungan Mematuhi ketentuan K3 (Keselamatan dan Kesehatan Kerja) Memiliki sertifikat ISO 14000:2015, 45001:2018 dan 9001:2015', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 922409);
