INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63378059', 63378059, 'analyze_legacy', 'Kota Dumai', 'kabkota', 'DINAS KOMUNIKASI, INFORMATIKA, STATISTIK DAN PERSANDIAN', 'Belanja Kawat/Faksimili/Internet/TV Berlangganan', 'Jasa Lainnya', 'E-Purchasing', 'Riau, Dumai (Kota)', 72000000, 'January 2026', 'APBD', 1, 1, '12 Bulan', 'Pengadaan Belanja Kawat/Faksmili/internet/Intranet/TV kabel /TV Satelit – Belanja Bandwith Jaringan Internet Wifi Publik 500MB', 'Target / sasaran yang ingin dicapai dalam kegiatan ini adalah Penyediaan akses Internet dengan Kapasitas 500 Mbps dengan jaminan Bandwidth Dedicated 1:1 via Fiber Optik dengan Sasaran : 1.Menyediakan Link Metro Wifi Publik pada 10 Titik Lokasi dengan rincian : a)Taman Bukit Gelanggang 3 Titik; b)Kuliner Janur Kuning; c)Kuliner Tanjung Jatu; d)Tatera; e)Mini Soccer; f)Stadion 2 Titik; g)Mall Pelayanan Publik. 2.Manajemen Bandwitdh terpusat di Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Dumai; 3.Bandwitdh ratio CIR (Committed Information Rate) 1:1 upstream dan downstream dengan sifat koneksi dedicated (non share/koneksi clear channel); 4.Media Akses menggunakan FO (Fiber Optic)/Jaringan Wireless; 5.Koneksi akhir menggunakan Optical Network Transmition (ONT) dan Ethernet (RJ45); 6.Minimum ketersediaan Service layer Availability (SLA) minimal 99,2% (714 Jam 15 Menit) dalam sebulan (720 Jam ) dengan masa kewajaran apabila internet down/mati sebesar 0,08%/ 5 jam 45 menit (pembulatan 6 jam/bulan) setiap bulanya dan mendapatkan laporan performance dan penggunaan (MRTG) jika SLA berkurang dari nilai tersebut dapat digunakan sebagai pengurang pembayaran pekerjaan kepada penyedia jasa layanan internet; 7.Fasilitas Layanan tenaga ahli atau engineer professional yang siap melayani dan memantau selama 24 jam x 7 hari dalam seminggu; 8.Batas Maksimal apabila terjadi down time pada layanan internet maksimal 3% dalam waktu setahun (akumulasi dalam waktu setahun); 9.Penyedia harus memiliki POP (Point of Presense) atau yang terdekat dengan Pemerintah Kota Dumai; 10.Penyedia harus memiliki kantor yang berdomisili di Kota Dumai; 11.Media koneksi/Backbone koneksi jaringan Bandwitdh menggunakan Fiber Optik;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 924152);
