INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63400346', 63400346, 'analyze_legacy', 'Kab. Nganjuk', 'kabkota', 'Rumah Sakit Daerah Nganjuk', 'Belanja Makan dan Minum', 'Barang', 'E-Purchasing', 'Jawa Timur, Nganjuk (Kab.)', 500000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Belanja makan dan minum merupakan pengadaan barang/jasa penunjang kegiatan operasional dan kegiatan resmi instansi yang bertujuan untuk mendukung kelancaran pelaksanaan pelayanan, rapat, peringatan hari besar, serta penjamuan tamu, dengan tetap memperhatikan standar kebersihan, kesehatan, dan ketentuan yang berlaku. 1. Kebutuhan Pokok (Air Mineral, Kopi, Teh, Gula, Makanan) 2. Makan Ruang OK 3. Rapat Kantor (Nasi Kotak) 4. Rapat Kantor (Snack Kotak) 5. Hari Jadi 6. Hari Kemerdekaan 7. Hari Raya 8. Hari Kesehatan 9. Tumpeng 10. Penjamuan Tamu', '1. Kebutuhan Pokok (Air Mineral, Kopi, Teh, Gula, Makanan) Uraian Spesifik: Penyediaan kebutuhan konsumsi dasar untuk mendukung kegiatan operasional dan pelayanan sehari-hari. Spesifikasi: Jenis: Air mineral, kopi, teh, gula, dan makanan Kondisi: Layak konsumsi, tidak kedaluwarsa Kemasan: Bersih dan aman Standar kesehatan: Memenuhi ketentuan higienitas pangan Output: Kebutuhan konsumsi tersedia sesuai kebutuhan kegiatan 2. Makan Ruang OK Uraian Spesifik: Penyediaan konsumsi makan bagi petugas/tenaga kesehatan yang bertugas di Ruang Operasi (OK) dalam rangka mendukung kelancaran pelayanan. Spesifikasi: Jenis: Makanan siap saji Porsi: Sesuai kebutuhan petugas Waktu penyediaan: Sesuai jadwal dinas Standar: Higienis dan layak konsumsi Output: Petugas memperoleh konsumsi tepat waktu 3. Rapat Kantor (Nasi Kotak) Uraian Spesifik: Penyediaan konsumsi makan berupa nasi kotak untuk peserta rapat kantor. Spesifikasi: Jenis: Nasi kotak Menu: Makanan utama dan lauk pendamping Kemasan: Kotak makanan higienis Jumlah: Sesuai jumlah peserta rapat Output: Konsumsi rapat tersedia dengan baik 4. Rapat Kantor (Snack Kotak) Uraian Spesifik: Penyediaan konsumsi berupa snack kotak untuk mendukung kegiatan rapat kantor. Spesifikasi: Jenis: Snack kotak Isi: Kue/snack dan minuman Kemasan: Rapi dan higienis Jumlah: Sesuai peserta rapat Output: Konsumsi rapat tersedia 5. Hari Jadi Uraian Spesifik: Penyediaan konsumsi dalam rangka peringatan Hari Jadi instansi/daerah. Spesifikasi: Jenis: Makan dan/atau snack kegiatan Porsi: Sesuai jumlah peserta Penyajian: Rapi dan layak Output: Kegiatan peringatan berjalan lancar 6. Hari Kemerdekaan Uraian Spesifik: Penyediaan konsumsi dalam rangka peringatan Hari Kemerdekaan Republik Indonesia. Spesifikasi: Jenis: Konsumsi kegiatan Jumlah: Menyesuaikan peserta kegiatan Standar: Higienis dan layak konsumsi Output: Kegiatan peringatan terlaksana dengan baik 7. Hari Raya Uraian Spesifik: Penyediaan konsumsi dalam rangka peringatan Hari Raya keagamaan. Spesifikasi: Jenis: Makan dan/atau snack Penyajian: Menyesuaikan kegiatan Standar: Higienis dan layak Output: Konsumsi kegiatan tersedia 8. Hari Kesehatan Uraian Spesifik: Penyediaan konsumsi untuk mendukung pelaksanaan kegiatan peringatan Hari Kesehatan. Spesifikasi: Jenis: Konsumsi kegiatan Jumlah: Sesuai peserta Penyajian: Bersih dan rapi Output: Kegiatan berjalan lancar 9. Tumpeng Uraian Spesifik: Penyediaan tumpeng sebagai konsumsi dan simbolisasi dalam kegiatan resmi instansi. Spesifikasi: Jenis: Tumpeng lengkap dengan lauk pauk Penyajian: Rapi dan layak Standar: Higienis dan layak konsumsi Output: Tumpeng siap digunakan dalam kegiatan 10. Penjamuan Tamu (Belanja Makan dan Minum) Uraian Spesifik: Penyediaan konsumsi makan dan minum dalam rangka penjamuan tamu resmi instansi. Spesifikasi: Jenis: Makan dan/atau minuman Penyajian: Sopan, rapi, dan layak Jumlah: Menyesuaikan jumlah tamu Output: Tamu terlayani dengan baik', 100000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 928281);
